ddlProposalOnlyNotExecuted.sql:
CREATE ROLE postgres SUPERUSER INHERIT NOCREATEROLE NOCREATEDB NOLOGIN NOREPLICATION NOBYPASSRLS;
DROP EXTENSION plpgsql RESTRICT;
SET ROLE postgres;
CREATE EXTENSION plpgsql WITH SCHEMA pg_catalog VERSION '1.0';
RESET ROLE;
ALTER ROLE postgres NOSUPERUSER;
CREATE ROLE uply_d8_target NOLOGIN;
CREATE ROLE uply_d8_member LOGIN CONNECTION LIMIT 7 VALID UNTIL '2035-01-01 00:00:00+00';
ALTER ROLE uply_d8_member SET statement_timeout='3s';
CREATE ROLE anon NOLOGIN;
CREATE ROLE authenticated NOLOGIN;
CREATE ROLE service_role NOLOGIN;
GRANT uply_d8_target TO postgres WITH ADMIN TRUE, INHERIT FALSE, SET FALSE GRANTED BY uply_d8_source_bootstrap;
GRANT uply_d8_target TO uply_d8_member WITH ADMIN FALSE, INHERIT TRUE, SET TRUE GRANTED BY postgres;

CREATE SCHEMA uply_d8 AUTHORIZATION postgres;
CREATE SCHEMA uply_d8_owner_only AUTHORIZATION postgres;
CREATE SCHEMA supabase_migrations AUTHORIZATION postgres;
CREATE FUNCTION public.review_chapter_practice_binding(uuid,uuid,integer,jsonb,boolean) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$SELECT '{"synthetic":true}'::jsonb$$;
ALTER FUNCTION public.review_chapter_practice_binding(uuid,uuid,integer,jsonb,boolean) OWNER TO postgres;

SET ROLE postgres;
CREATE TYPE uply_d8.state AS ENUM ('open','closed');
CREATE DOMAIN uply_d8.nonnegative AS numeric CHECK (VALUE >= 0);
CREATE SEQUENCE uply_d8.sample_seq;
SELECT setval('uply_d8.sample_seq',20,true);
CREATE TABLE uply_d8.samples(id bigint PRIMARY KEY,nullable_text text,amount numeric(12,4) NOT NULL,happened_at timestamptz NOT NULL,label text NOT NULL,active boolean NOT NULL,state uply_d8.state NOT NULL,quota uply_d8.nonnegative NOT NULL DEFAULT 0);
CREATE INDEX samples_label_idx ON uply_d8.samples(label);
INSERT INTO uply_d8.samples(id,nullable_text,amount,happened_at,label,active,state) VALUES (1,NULL,12.3400,'2020-01-02 03:04:05+00','alpha',true,'open'),(2,'',-5.2500,'2020-06-01 00:00:00.000001+00','beta',false,'closed'),(3,E'한글 quote \' and newline\n',0.0000,'2021-02-03 04:05:06.123456+00','gamma',true,'open');
CREATE VIEW uply_d8.sample_view AS SELECT id,label,nullable_text FROM uply_d8.samples;
CREATE MATERIALIZED VIEW uply_d8.sample_materialized AS SELECT id,label,amount FROM uply_d8.samples;
CREATE FUNCTION uply_d8.render_label(t text) RETURNS text LANGUAGE plpgsql IMMUTABLE AS $$BEGIN RETURN CASE WHEN t IS NULL THEN NULL ELSE 'd8:'||t END; END;$$;
ALTER TABLE uply_d8.samples ENABLE ROW LEVEL SECURITY;
CREATE POLICY sample_read ON uply_d8.samples FOR SELECT TO uply_d8_member USING (active);
CREATE TABLE supabase_migrations.schema_migrations(version text PRIMARY KEY,statements text[],name text);
INSERT INTO supabase_migrations.schema_migrations VALUES ('D8_SYNTH_000',NULL,'synthetic_null'),('D8_SYNTH_001',ARRAY['SELECT 1;'],'synthetic_array');
GRANT USAGE ON SCHEMA uply_d8 TO uply_d8_member,anon;
GRANT SELECT ON uply_d8.samples TO uply_d8_member;
GRANT SELECT(nullable_text) ON uply_d8.samples TO anon;
GRANT USAGE ON SEQUENCE uply_d8.sample_seq TO uply_d8_member;
REVOKE ALL ON FUNCTION uply_d8.render_label(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION uply_d8.render_label(text) TO uply_d8_member;
REVOKE ALL ON FUNCTION public.review_chapter_practice_binding(uuid,uuid,integer,jsonb,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.review_chapter_practice_binding(uuid,uuid,integer,jsonb,boolean) TO authenticated,service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA uply_d8 GRANT SELECT ON TABLES TO uply_d8_member;
CREATE TABLE uply_d8.default_acl_probe(id integer);
GRANT ALL ON SCHEMA uply_d8_owner_only TO postgres;
CREATE TABLE uply_d8_owner_only.owner_probe(id integer);
GRANT ALL ON TABLE uply_d8_owner_only.owner_probe TO postgres;
RESET ROLE;

